/* From Uiverse.io by SyedShahzaib7  - Tags: simple, login, 3d, social, gradient, form, submit, login form */
.__UIV_SCOPE__ .wrapper {
  width: 420px;
  background: rgb(2, 0, 36);
  background: linear-gradient(
    90deg,
    rgba(2, 0, 36, 1) 9%,
    rgba(9, 9, 121, 1) 68%,
    rgba(0, 91, 255, 1) 97%
  );
  backdrop-filter: blur(9px);
  color: #fff;
  border-radius: 12px;
  padding: 30px 40px;
}
.__UIV_SCOPE__ .form-login {
  font-size: 36px;
  text-align: center;
}
.__UIV_SCOPE__ .wrapper .input-box {
  position: relative;
  width: 100%;
  height: 50px;

  margin: 30px 0;
}
.__UIV_SCOPE__ .input-box input {
  width: 100%;
  height: 100%;
  background: transparent;
  border: none;
  outline: none;
  border: 2px solid rgba(255, 255, 255, 0.2);
  border-radius: 40px;
  font-size: 16px;
  color: #fff;
  padding: 20px 45px 20px 20px;
}
.__UIV_SCOPE__ .input-box input::placeholder {
  color: #fff;
}

.__UIV_SCOPE__ .wrapper .remember-forgot {
  display: flex;
  justify-content: space-between;
  font-size: 14.5px;
  margin: -15px 0 15px;
}
.__UIV_SCOPE__ .remember-forgot label input {
  accent-color: #fff;
  margin-right: 3px;
}
.__UIV_SCOPE__ .remember-forgot a {
  color: #fff;
  text-decoration: none;
}
.__UIV_SCOPE__ .remember-forgot a:hover {
  text-decoration: underline;
}
.__UIV_SCOPE__ .wrapper .btn {
  width: 150px;
  height: 45px;
  background: #fff;
  border: none;
  outline: none;
  border-radius: 40px;
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
  cursor: pointer;
  font-size: 16px;
  color: #333;
  font-weight: 600;
  margin-left: 90px;
  margin-top: 10px;
}
.__UIV_SCOPE__ .wrapper .register-link {
  font-size: 14.5px;
  text-align: center;
  margin: 20px 0 15px;
}
.__UIV_SCOPE__ .register-link p a {
  color: #fff;
  text-decoration: none;
  font-weight: 600;
}
.__UIV_SCOPE__ .register-link p a:hover {
  text-decoration: underline;
}
